def transform(grid):
    h, w = len(grid), len(grid[0])
    centers = []

    # Each object is a four-cell diamond: its four cardinal neighbors are 2.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r - 1][c] == 2 and grid[r + 1][c] == 2
                    and grid[r][c - 1] == 2 and grid[r][c + 1] == 2):
                centers.append((r, c))

    out = [row[:] for row in grid]

    # Join consecutive diamonds sharing a row or column, between their tips.
    for r in range(h):
        cols = sorted(c for rr, c in centers if rr == r)
        for c1, c2 in zip(cols, cols[1:]):
            for c in range(c1 + 2, c2 - 1):
                if out[r][c] == 0:
                    out[r][c] = 1

    for c in range(w):
        rows = sorted(r for r, cc in centers if cc == c)
        for r1, r2 in zip(rows, rows[1:]):
            for r in range(r1 + 2, r2 - 1):
                if out[r][c] == 0:
                    out[r][c] = 1

    return out
